#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, cnt = 0;
    cin >> n;

    vector<int> a(n);
    for (int i = 0; i < n; i++)
        cin >> a[i];

    sort(a.begin(), a.end());

    for (int i = 0; i < n; i++) {
        if ((a[i] == 0 || a[i] == 1) && i != n - 1)
            i++;

        for (int j = 0; j < n - 1; j++) {
            if (i == j)
                j++;

            if (a[i] != 0 && a[j] != 0) {
                if (a[i] % a[j] == 0 || a[j] % a[i] == 0)
                    a[j] = 0;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        if (a[i] != 0) {
            if (a[i] == 1 && cnt == 0)
                cnt++;
            else if (a[i] == 1)
                i++;
            else
                cnt++;
        }
    }

    cout << cnt;
    return 0;
}

